### Define Sales Report API in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/static-report-generation.mdx

Defines a REST API endpoint for fetching sales reports. It accepts date range and optional region parameters, queries a materialized view using parameterized SQL, and returns typed JSON. Ensure the `dailySalesMV` is correctly defined and data is ingested.

```typescript
import { Api } from "@514labs/moose-lib";
import { dailySalesMV } from "../views/DailySalesSummary";

// Define query parameters
export interface SalesReportParams {
  startDate: string;   // Format: YYYY-MM-DD
  endDate: string;     // Format: YYYY-MM-DD
  region?: string;     // Optional filter
}

// Define response interface
export interface SalesReportResponse {
  saleDate: string;
  region: string;
  productCategory: string;
  transactionCount: number;
  totalQuantity: number;
  totalRevenue: number;
}

// Create the API endpoint
export const salesReportApi = new Api<SalesReportParams, SalesReportResponse[]>(
  "sales-report",
  async ({ startDate, endDate, region }, { client, sql }) => {
    // Access the target table from the materialized view
    const targetTable = dailySalesMV.targetTable;

    // Build query with optional region filter
    // Note: We use separate queries for clarity. Production code could
    // consolidate these using conditional query building.
    let query;
    if (region) {
      query = sql`
        SELECT
          saleDate,
          region,
          productCategory,
          sum(transactionCount) AS transactionCount,
          sum(totalQuantity) AS totalQuantity,
          sum(totalRevenue) AS totalRevenue
        FROM ${targetTable}
        WHERE saleDate BETWEEN ${startDate} AND ${endDate}
          AND region = ${region}
        GROUP BY saleDate, region, productCategory
        ORDER BY saleDate DESC, totalRevenue DESC
      `;
    } else {
      query = sql`
        SELECT
          saleDate,
          region,
          productCategory,
          sum(transactionCount) AS transactionCount,
          sum(totalQuantity) AS totalQuantity,
          sum(totalRevenue) AS totalRevenue
        FROM ${targetTable}
        WHERE saleDate BETWEEN ${startDate} AND ${endDate}
        GROUP BY saleDate, region, productCategory
        ORDER BY saleDate DESC, totalRevenue DESC
      `;
    }

    const result = await client.query.execute<SalesReportResponse>(query);
    return result.json();
  }
);

```

