    `;

    const result = await client.query.execute<TopProductsResponse>(query);
    return result.json();
  }
);

import { Api } from "@514labs/moose-lib";
import { conversionFunnelMV } from "../views/ConversionFunnel";

// Define query parameters (no filters needed for funnel)
export interface ConversionFunnelParams {}

// Define response interface
export interface ConversionFunnelResponse {
  step: string;
  unique_users: number;
  total_events: number;
}

// Create the API endpoint for conversion funnel
export const conversionFunnelApi = new Api<ConversionFunnelParams, ConversionFunnelResponse[]>(
  "conversion-funnel",
  async ({}, { client, sql }) => {
    // Access the target table from the materialized view
    const targetTable = conversionFunnelMV.targetTable;

    const query = sql`
      SELECT
        step,
        unique_users,
        total_events
      FROM ${targetTable}
      ORDER BY
        CASE
          WHEN step = 'view' THEN 1
          WHEN step = 'cart' THEN 2
          WHEN step = 'purchase' THEN 3
        END
    `;

    const result = await client.query.execute<ConversionFunnelResponse>(query);
    return result.json();
  }
);

import { Api } from "@514labs/moose-lib";
import { hourlyActivityMV } from "../views/HourlyActivity";

// Define query parameters
export interface HourlyActivityParams {
  startDate?: string;  // Format: YYYY-MM-DD
  endDate?: string;    // Format: YYYY-MM-DD
  event_type?: string; // Optional filter by event type
}

// Define response interface
export interface HourlyActivityResponse {
  hour: string;
  event_type: string;
  event_count: number;
}

// Create the API endpoint for hourly activity
export const hourlyActivityApi = new Api<HourlyActivityParams, HourlyActivityResponse[]>(
  "hourly-activity",
  async ({ startDate, endDate, event_type }, { client, sql }) => {
    // Access the target table from the materialized view
    const targetTable = hourlyActivityMV.targetTable;

    // Build query with optional filters
    let whereClause = '';
    if (startDate) {
      whereClause += `hour >= '${startDate}'`;
    }
    if (endDate) {
      whereClause += whereClause ? ` AND hour <= '${endDate} 23:59:59'` : `hour <= '${endDate} 23:59:59'`;
    }
    if (event_type) {
      whereClause += whereClause ? ` AND event_type = '${event_type}'` : `event_type = '${event_type}'`;
    }

    const query = sql`
      SELECT
        formatDateTime(hour, '%Y-%m-%d %H:%M:%S') AS hour,
        event_type,
        event_count
      FROM ${targetTable}
      ${whereClause ? `WHERE ${whereClause}` : ''}
      ORDER BY hour ASC, event_type
    `;

    const result = await client.query.execute<HourlyActivityResponse>(query);
    return result.json();
  }
);

