const fs = require('fs');
const path = require('path');

// Function to load all seed events and POST them to the ingest endpoint
async function loadSeedData() {
  const seedDataDir = '/data/events';
  const ingestUrl = 'http://localhost:4010/ingest/ProductEvent';

  try {
    // Read all event files
    const files = fs.readdirSync(seedDataDir)
      .filter(file => file.endsWith('.json'))
      .sort();

    console.log(`Found ${files.length} seed event files`);

    for (const file of files) {
      const filePath = path.join(seedDataDir, file);
      const eventData = JSON.parse(fs.readFileSync(filePath, 'utf8'));

      // Convert event_ts to proper Date format
      eventData.event_ts = new Date(eventData.event_ts);

      console.log(`Loading event: ${eventData.event_id} (${eventData.event_type})`);

      try {
        const response = await fetch(ingestUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(eventData)
        });

        if (response.ok) {
          console.log(`✓ Successfully loaded ${eventData.event_id}`);
        } else {
          console.error(`✗ Failed to load ${eventData.event_id}: ${response.status} ${response.statusText}`);
        }
      } catch (error) {
        console.error(`✗ Error loading ${eventData.event_id}:`, error.message);
      }

      // Small delay between requests
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    console.log('Finished loading seed data');
  } catch (error) {
    console.error('Error loading seed data:', error);
  }
}

// Function to test API endpoints
async function testApis() {
  const baseUrl = 'http://localhost:4010/api';
  const apis = [
    '/top-products?limit=10',
    '/conversion-funnel',
    '/hourly-activity'
  ];

  console.log('\nTesting API endpoints...');

  for (const endpoint of apis) {
    try {
      const startTime = Date.now();
      const response = await fetch(`${baseUrl}${endpoint}`);
      const endTime = Date.now();
      const responseTime = endTime - startTime;

      if (response.ok) {
        const data = await response.json();
        console.log(`✓ ${endpoint} - ${responseTime}ms - ${JSON.stringify(data).length} bytes`);
        if (responseTime > 200) {
          console.warn(`⚠ Response time (${responseTime}ms) exceeds 200ms target`);
        }
      } else {
        console.error(`✗ ${endpoint} - ${response.status} ${response.statusText}`);
      }
    } catch (error) {
      console.error(`✗ ${endpoint} - Error: ${error.message}`);
    }
  }
}

// Main execution
if (require.main === module) {
  const command = process.argv[2];

  if (command === 'load') {
    loadSeedData();
  } else if (command === 'test') {
    testApis();
  } else if (command === 'all') {
    loadSeedData().then(() => {
      console.log('\nWaiting 5 seconds for data to be processed...');
      setTimeout(testApis, 5000);
    });
  } else {
    console.log('Usage: node load_seed_data.js [load|test|all]');
    console.log('  load - Load seed data into Moose');
    console.log('  test - Test API endpoints');
    console.log('  all  - Load data then test APIs');
  }
}

module.exports = { loadSeedData, testApis };

